function renderSearchTagMenu(prefix){let q=($(prefix+'SearchTagInput')?.value||'').trim().toLowerCase(),sel=prefix==='item'?selectedItemTags:selectedTags,all=allTags().filter(t=>!q||t.toLowerCase().includes(q)),recent=recentTags().filter(t=>all.includes(t)),rest=all.filter(t=>!recent.includes(t));let body=$(prefix+'SearchMenuBody');if(!body)return;let html='';if(sel.length)html+=`<button type="button" class="tag-option new" onclick="clearSearchTags('${prefix}')">すべて解除</button>`;if(recent.length)html+='<div class="tag-menu-title">最近使ったタグ</div><div class="tag-options">'+recent.map(t=>`<button type="button" class="tag-option ${sel.includes(t)?'selected':''}" onclick="toggleSearchTag('${prefix}',${JSON.stringify(t).replace(/</g,'\\u003c')})">#${esc(t)}${sel.includes(t)?' ✓':''}</button>`).join('')+'</div>';if(rest.length)html+='<div class="tag-menu-title">すべてのタグ</div><div class="tag-options">'+rest.map(t=>`<button type="button" class="tag-option ${sel.includes(t)?'selected':''}" onclick="toggleSearchTag('${prefix}',${JSON.stringify(t).replace(/</g,'\\u003c')})">#${esc(t)}${sel.includes(t)?' ✓':''}</button>`).join('')+'</div>';if(!all.length)html+='<div class="tag-empty">該当するタグがありません。</div>';body.innerHTML=html}
function toggleSearchTag(prefix,tag){let arr=prefix==='item'?selectedItemTags:selectedTags,i=arr.indexOf(tag);if(i>=0)arr.splice(i,1);else arr.push(tag);render();}
